import { walletAbi } from './wallet-abi.js';
import { walletReceiptLog } from './wallet-receipt.js';
import { abi as abiCOINFLIP } from '../chain/generated/coinflip.js';
import { abi as abiGAME } from '../chain/generated/game.js';
// Permissionless miner work: mineRun(0), where zero selects the default estimate multiplier.
// Probe, estimate and send must use the same arguments, including the automatic settlement paths.

import { sendTx, getProvider, ethers, gasEstimateWithHeadroom } from './contracts.js';
import { requireStaticCall } from './static-call.js';
import { decodeRevertReason, register } from './reason-map.js';
import { CONTRACTS } from './chain-config.js';
import { get, getActingAddress } from './store.js';
import { sharedReadProvider } from './read-provider.js';
import { transactionFeeData } from './transaction-fees.js';
import { flipFromChain } from './token-units.js';
import { miningGasBounds } from './mining-gas-profile.js';

// Verified: DegenerusGame.sol:398 and a live eth_call (see header). Declaring
// `error NoWork()` here is what lets ethers decode the empty-queue revert by
// name instead of handing back an unnamed CALL_EXCEPTION. `RngNotReady()` is
// the advance leg's revert while the day's VRF word is outstanding
// (DegenerusGameAdvanceModule.sol rngGate), declared so the reason-map names it.
const MINE_FLIP_ABI = [
  'function mineRun() external',
  'error NoWork()',
  'error RngNotReady()',
];

/** The accepted stake credit immediately preceding this wallet's mining bounty. */
export function readMineFlipStakeCredit(receipt, player) {
  if (Number(receipt?.status) !== 1 || !player) return null;
  const miner = String(player).toLowerCase();
  let pending = null;
  let credit = null;
  for (const log of receipt.logs || []) {
    const address = String(log?.address || '').toLowerCase();
    try {
      const iface = new ethers.Interface(address === String(CONTRACTS.COINFLIP).toLowerCase() ? abiCOINFLIP : abiGAME);
      const event = walletReceiptLog(log, iface);
      if (address === String(CONTRACTS.COINFLIP).toLowerCase()
        && event?.name === 'CoinflipStakeUpdated' && event.args.player.toLowerCase() === miner) {
        pending = {
          day: Number(event.args.day),
          amountWei: flipFromChain(event.args.amount).toString(),
          totalWei: flipFromChain(event.args.newTotal).toString(),
        };
      } else if (address === String(CONTRACTS.GAME).toLowerCase()
        && event?.name === 'MinerBounty' && event.args.miner.toLowerCase() === miner) {
        if (pending && BigInt(pending.amountWei) <= flipFromChain(event.args.flipAmount)) credit = pending;
        pending = null;
      }
    } catch (_error) { /* Ignore unrelated receipt events. */ }
  }
  return credit;
}

/** Sum only confirmed game bounties paid to this crank's connected wallet. */
export function readMineFlipReward(receipt, player) {
  if (Number(receipt?.status) !== 1 || !player) return 0n;
  const miner = String(player).toLowerCase();
  const game = String(CONTRACTS.GAME).toLowerCase();
  let reward = 0n;
  for (const log of receipt.logs || []) {
    if (String(log?.address || '').toLowerCase() !== game) continue;
    try {
      const iface = new ethers.Interface(abiGAME);
      const event = walletReceiptLog(log, iface);
      if (event?.name === 'MinerBounty' && event.args.miner.toLowerCase() === miner) {
        // FLIP: whole tokens on chain since audit b05ea7c50; token wei here.
        reward += flipFromChain(event.args.flipAmount);
      }
    } catch (_error) { /* Other game events do not describe the miner's reward. */ }
  }
  return reward;
}

export function mineFlipArgs() { return [0]; }

const CRANK_NAME = 'mineRun';
// Match the sim's Sepolia reservoir budget. Base retains its pre-Glamsterdam
// limits. Adaptive mining can estimate a no-op, so Sepolia uses a fixed budget.
const { min: MINE_FLIP_MIN_GAS_LIMIT, max: MINE_FLIP_MAX_GAS_LIMIT } = miningGasBounds();

let _contractFactory = null;

/** Test-only: replace the `new Contract(...)` construction with a fake. */
export function __setContractFactoryForTest(fn) {
  _contractFactory = fn;
}

/** Test-only: clear the injected factory; subsequent calls use the real path. */
export function __resetContractFactoryForTest() {
  _contractFactory = null;
}

function _buildGameContract(signerOrProvider) {
  if (_contractFactory) return _contractFactory(signerOrProvider);
  return new ethers.Contract(CONTRACTS.GAME, walletAbi(MINE_FLIP_ABI, abiGAME), signerOrProvider);
}

function _structuredRevertError(error, context) {
  const decoded = decodeRevertReason(error);
  const wrapped = new Error(decoded.userMessage || `Failed: ${context}`);
  wrapped.code = decoded.code;
  wrapped.userMessage = decoded.userMessage;
  wrapped.recoveryAction = decoded.recoveryAction;
  wrapped.cause = error;
  return wrapped;
}

/**
 * True when the revert is the crank's "queue is empty" signal rather than a
 * real failure. Matched on the decoded code AND on the raw text: the deployed
 * build predates some reason-map registrations, and a custom error the local ABI
 * does not know about surfaces as an unnamed `CALL_EXCEPTION` whose data is the
 * NoWork selector.
 */
const NO_WORK_SELECTOR = '0x5c78c46f'; // keccak256("NoWork()")[0:4]

// Registered under BOTH keys at module load, mirroring claims.js. The name path
// fires when ethers decodes against our ABI fragment; the selector path covers a
// deploy whose revert data we can read but whose error we never declared.
register('NoWork', {
  code: 'NoWork',
  userMessage: 'Nothing to mine right now.',
  recoveryAction: 'The queue is empty — check back after the next day rolls over.',
});
register(NO_WORK_SELECTOR, {
  code: 'NoWork',
  userMessage: 'Nothing to mine right now.',
  recoveryAction: 'The queue is empty — check back after the next day rolls over.',
});

export function isNoWorkRevert(error) {
  if (!error) return false;
  const decoded = decodeRevertReason(error);
  if (decoded && decoded.code === 'NoWork') return true;
  const data = error?.data ?? error?.info?.error?.data ?? error?.cause?.data;
  if (typeof data === 'string' && data.toLowerCase().startsWith(NO_WORK_SELECTOR)) return true;
  return /\bNoWork\b/.test(String(error?.message ?? ''));
}

/**
 * True when the simulation reached the contract and it reverted — the chain's
 * own answer that a send right now would fail (e.g. `RngNotReady` while the
 * advance leg waits on VRF). Revert data is the discriminator: a transport
 * fault (timeout, dead RPC) carries none, and only that stays "unknown".
 */
function _isContractRevert(error) {
  if (!error) return false;
  if (error.revert) return true;
  const data = error?.data ?? error?.info?.error?.data ?? error?.cause?.data;
  return typeof data === 'string' && /^0x[0-9a-f]{8}/i.test(data);
}

async function _mineFlipGasBudget(contract, signer, provider) {
  // BrowserProvider supplies all three methods. The capability guard keeps
  // read-only/test runners degraded rather than fabricating an affordability
  // result from incomplete RPC data.
  if (typeof provider?.getBalance !== 'function'
    || typeof provider?.getFeeData !== 'function'
    || typeof signer?.getAddress !== 'function') return null;
  const connected = typeof contract?.connect === 'function' ? contract.connect(signer) : contract;
  if (typeof connected?.[CRANK_NAME]?.estimateGas !== 'function') return null;

  try {
    const [estimateRaw, address, feeData] = await Promise.all([
      connected[CRANK_NAME].estimateGas(...mineFlipArgs()),
      signer.getAddress(),
      transactionFeeData(provider),
    ]);
    const estimate = BigInt(estimateRaw ?? 0);
    if (estimate <= 0n || estimate > MINE_FLIP_MAX_GAS_LIMIT) {
      return { affordable: false, reason: 'gas-limit', estimate };
    }
    const padded = gasEstimateWithHeadroom(estimate);
    const gasLimit = padded > MINE_FLIP_MAX_GAS_LIMIT
      ? MINE_FLIP_MAX_GAS_LIMIT
      : padded < MINE_FLIP_MIN_GAS_LIMIT
        ? MINE_FLIP_MIN_GAS_LIMIT
        : padded;
    const feeRaw = feeData?.maxFeePerGas ?? feeData?.gasPrice;
    if (feeRaw == null) return null;
    const feePerGas = BigInt(feeRaw);
    const balance = BigInt(await provider.getBalance(address));
    const requiredWei = gasLimit * feePerGas;
    return {
      affordable: balance >= requiredWei,
      reason: balance >= requiredWei ? null : 'insufficient-gas',
      balanceWei: balance,
      requiredWei,
      estimate,
      gasLimit,
    };
  } catch (error) {
    return { affordable: false, reason: 'gas-unknown', error };
  }
}

/**
 * Ask the chain whether the crank has anything to do, without spending gas.
 *
 * Never throws, and distinguishes "no work" from "could not tell": an
 * unreachable provider reports `known: false`, so a dead RPC can neither light
 * the widget up nor claim the queue is empty.
 *
 * @param {{player?: string}} [args]
 * @returns {Promise<{hasWork: boolean, known: boolean, reason?: string,
 *   error?: Error, gasLimit?: bigint, balanceWei?: bigint, requiredWei?: bigint}>}
 */
export async function probeMineFlip({ player } = {}) {
  const walletProvider = getProvider();
  if (!walletProvider) return { hasWork: false, known: false };

  let signer = null;
  try {
    signer = await walletProvider.getSigner();
  } catch (_e) {
    // Read-only browsing (no wallet): the crank is a write, so there is nothing
    // to offer. Report "unknown" rather than "no work" — they are different.
    return { hasWork: false, known: false };
  }

  // Work discovery is a pure, permissionless eth_call. Route it through the
  // shared public reader so an expected NoWork revert does not surface as a
  // MetaMask -32603. Preserve msg.sender semantics with an explicit `from`.
  const readProvider = sharedReadProvider() || walletProvider;
  const contract = _buildGameContract(readProvider);
  let from = player || null;
  if (!from) {
    try { from = await signer.getAddress(); } catch (_e) { from = null; }
  }
  const sim = await requireStaticCall(
    contract,
    CRANK_NAME,
    [...mineFlipArgs(), ...(from ? [{ from }] : [])],
  );
  if (sim.ok) {
    // Fee and balance are public chain reads. Keep passive affordability
    // discovery off the injected wallet (which may not implement every fee
    // RPC), while the signer-connected estimate and actual send stay intact.
    const budget = await _mineFlipGasBudget(contract, signer, readProvider);
    if (budget && !budget.affordable) {
      return {
        hasWork: false,
        known: budget.reason === 'insufficient-gas' || budget.reason === 'gas-limit',
        reason: budget.reason,
        error: budget.error,
        balanceWei: budget.balanceWei,
        requiredWei: budget.requiredWei,
      };
    }
    return { hasWork: true, known: true, gasLimit: budget?.gasLimit };
  }
  if (isNoWorkRevert(sim.error)) return { hasWork: false, known: true };

  // Any other contract revert is still a definite "not now": during the VRF
  // wait `_advanceDue()` stays true, so the router re-enters advanceGame and
  // reverts RngNotReady on every call until the word lands.
  if (_isContractRevert(sim.error)) {
    return { hasWork: false, known: true, reason: 'reverted', error: sim.error };
  }

  // An RPC fault: not work, and not a reliable "empty".
  return { hasWork: false, known: false, error: sim.error };
}

/**
 * Run the crank. Pre-flights through the same probe so a NoWork queue surfaces
 * as a plain message rather than a wallet prompt for a tx that must revert.
 *
 * @param {{player?: string}} [args]
 * @returns {Promise<{receipt: import('ethers').TransactionReceipt, entrypoint: string}>}
 */
export async function mineRun({ player } = {}) {
  // Permissionless crank: the tx signs (and its bounty pays) the CONNECTED
  // wallet regardless of switcher mode, so fall through to it when the acting
  // address is null (view/combined modes are read-only for player-owned
  // writes, but the keeper crank belongs to whoever holds the keys).
  const playerArg = player ?? getActingAddress() ?? get('connected.address');
  if (!playerArg) throw new Error('Wallet not connected.');

  const probe = await probeMineFlip({ player: playerArg });
  if (probe.reason === 'reverted') {
    throw _structuredRevertError(probe.error, `static-call ${CRANK_NAME}`);
  }
  if (probe.known && !probe.hasWork) {
    if (probe.reason === 'insufficient-gas') {
      const err = new Error('Not enough ETH for Mine FLIP gas.');
      err.code = 'InsufficientGas';
      err.userMessage = 'Not enough ETH for Mine FLIP gas.';
      throw err;
    }
    const err = new Error('Nothing to mine right now.');
    err.code = 'NoWork';
    err.userMessage = 'Nothing to mine right now.';
    throw err;
  }
  if (!probe.known && probe.error) {
    throw _structuredRevertError(probe.error, `static-call ${CRANK_NAME}`);
  }

  // Phase 58 chokepoint — closure form mandatory (stale-signer capture guard).
  const receipt = await sendTx((s) => {
    const contract = _buildGameContract(s);
    const gasLimit = probe.gasLimit != null && BigInt(probe.gasLimit) > MINE_FLIP_MIN_GAS_LIMIT
      ? BigInt(probe.gasLimit)
      : MINE_FLIP_MIN_GAS_LIMIT;
    return contract.mineRun(...mineFlipArgs(), { gasLimit });
  }, 'Mine FLIP');
  return { receipt, entrypoint: CRANK_NAME };
}

/**
 * The gas limit a mineRun send carries: the live estimate plus the shared headroom, clamped to
 * [MINE_FLIP_MIN_GAS_LIMIT, MINE_FLIP_MAX_GAS_LIMIT]; the floor when no estimate is available.
 * Shared by every UI path that drives the chain's work through mineRun — since audit 18490c6fe
 * it is the only door (openBoxes, requestLootboxRng and settleDecimatorWinners are gone).
 */
export async function mineFlipGasLimit(contract) {
  try {
    const estimate = BigInt(await contract?.mineRun?.estimateGas?.(...mineFlipArgs()) ?? 0);
    if (estimate <= 0n) return MINE_FLIP_MIN_GAS_LIMIT;
    const padded = gasEstimateWithHeadroom(estimate);
    return padded > MINE_FLIP_MAX_GAS_LIMIT ? MINE_FLIP_MAX_GAS_LIMIT
      : padded < MINE_FLIP_MIN_GAS_LIMIT ? MINE_FLIP_MIN_GAS_LIMIT : padded;
  } catch (_e) {
    return MINE_FLIP_MIN_GAS_LIMIT;
  }
}

export const _testing = {
  CRANK_NAME,
  NO_WORK_SELECTOR,
  MINE_FLIP_MIN_GAS_LIMIT,
  MINE_FLIP_MAX_GAS_LIMIT,
  mineFlipGasBudget: _mineFlipGasBudget,
};
